query stored_product {
 require $builder HAS_FIELD $stored;
 require $stored TYPE $product;
 different $builder $product;
 require $builder HAS_METHOD $initialize;
 require $creation ALLOCATES_TYPE $product;
 any {
  require $stored ASSIGNED_FROM $creation;
  require $initialize HAS_CALL $creation;
 } or {
  require $container ALLOCATES_TYPE $builder;
  require $initialize HAS_CALL $container;
  require $container HAS_INITIALIZER $initializer;
  require $initializer INITIALIZES_FIELD $stored;
  require $initializer STORES_VALUE $creation;
 }
 require $builder HAS_METHOD $step;
 callable(constructor: false, static: false) as $step;
 require $step HAS_PARAMETER $input;
 parameter(receiver: false) as $input;
 require $step HAS_OPERATION $write;
 require $write FINAL_MEMBER_INPUT $input;
 require $write ASSIGNMENT_TARGET $member;
 path $member MEMBER_OF{1,8} $stored as $member_path;
 require $builder HAS_METHOD $finish;
 callable(constructor: false, static: false) as $finish;
 different $step $finish;
 any {
  require $finish RETURNS_VALUE $result;
  require $result LOADED_FROM $stored;
 } or {
  match "prototype.derived_copy"(unit:$product,receiver:$stored,copy:$copy);
  require $finish RETURNS_CALL $copy;
 }
 emit $builder, $finish, $product, $stored, $initialize, $creation, $step, $input, $write, $member;
}

